using System;using System.Linq;using System.IO;using System.Collections.Generic;using UnityEngine;using CatGunner.Runtime;
public static class InspectPenguinParticleDetails
{
 public static string Run(){var all=GameClient.Instance.gameObject.scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<ParticleSystem>(true));var items=all.Where(p=>p.GetComponent<ParticleSystemRenderer>().sharedMaterial?.mainTexture?.name=="effects-00").Take(8).Select(p=>{var m=p.main;var r=p.GetComponent<ParticleSystemRenderer>();var v=new List<ParticleSystemVertexStream>();r.GetActiveVertexStreams(v);return new{p.name,parent=p.transform.parent.name,size3D=m.startSize3D,size=m.startSizeMultiplier,x=m.startSizeXMultiplier,y=m.startSizeYMultiplier,z=m.startSizeZMultiplier,scale=p.transform.lossyScale.ToString(),r.renderMode,streams=v.Select(s=>s.ToString()),trails=p.trails.enabled,trailMaterial=r.trailMaterial?.name,trailShader=r.trailMaterial?.shader.name,trailTexture=r.trailMaterial?.mainTexture?.name,color=r.sharedMaterial.GetColor("_Color").ToString(),sheet=p.textureSheetAnimation.enabled,sizeAxes=p.sizeOverLifetime.separateAxes,sizeX=p.sizeOverLifetime.x.constantMax,sizeY=p.sizeOverLifetime.y.constantMax,sizeZ=p.sizeOverLifetime.z.constantMax,live=p.particleCount,rotate3D=m.startRotation3D,rotateX=m.startRotationXMultiplier,rotateY=m.startRotationYMultiplier,rotateZ=m.startRotationZMultiplier};}).ToArray();string result=Newtonsoft.Json.JsonConvert.SerializeObject(items,Newtonsoft.Json.Formatting.Indented);File.WriteAllText(Path.GetFullPath(Application.dataPath+"/../../../art/reskin/penguin-expedition/grip-expression-v2/particle-details.json"),result);return "Saved particle size and rotation details";}
}
